```js
await page.goto('/ops/radar');
await expect(page).toHaveURL(/\/ops\/radar/);

// Radar feed: the list of radar items; locked card: the card marked locked.
const feed = page.getByRole('list').first();
await expect(feed).toBeVisible();
const lockedCard = page.getByRole('article').filter({ hasText: /locked/i }).first();
await expect(lockedCard).toBeVisible();

// Both should stack in a column, not lay out in a row.
await expect(feed).toHaveCSS('flex-direction', 'column');
await expect(lockedCard).toHaveCSS('flex-direction', 'column');
```

